export const legalDocuments = Object.freeze(
  Object.fromEntries(LEGAL_LOCALES.map((locale) => [locale, Object.freeze({ terms: terms[locale], privacy: privacy[locale] })]))
);

export function getLegalDocument(locale, kind) {
  const localized = legalDocuments[locale] ?? legalDocuments.en;
  return localized[kind];
}

export function legalDocumentToMarkdown(document) {
  const sections = document.sections.map((section) => {
    const parts = [`## ${section.heading}`, ...(section.paragraphs ?? [])];
    if (section.bullets?.length) parts.push(section.bullets.map((item) => `- ${item}`).join('\n'));
    for (const subsection of section.subsections ?? []) {
      parts.push(`### ${subsection.heading}`, ...(subsection.paragraphs ?? []));
    }
    return parts.join('\n\n');
  });
  return [`# ${document.title}`, document.intro, `**${document.updatedLabel}:** ${document.updated}`, ...sections].join('\n\n') + '\n';
}
